package com.feather.browser;
import android.app.Activity;import android.os.Bundle;import android.content.SharedPreferences;import android.graphics.Bitmap;import android.graphics.BitmapFactory;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;import android.net.Uri;import org.json.JSONObject;import java.net.URLEncoder;import java.util.UUID;import java.util.concurrent.TimeUnit;import okhttp3.*;import okio.ByteString;
public class MainActivity extends Activity {
 OkHttpClient client; WebSocket ws; EditText host,token,url; ImageView page; TextView status; String sid="q10-"+UUID.randomUUID().toString().substring(0,8); float sx,sy,lx,ly; boolean moved;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(11);b.setAllCaps(false);return b;}
 EditText field(String s,boolean p){EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(12);e.setHint(s);e.setTextColor(-1);e.setHintTextColor(0xffaaaaaa);e.setBackgroundColor(0xff303944);if(p)e.setInputType(129);return e;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);client=new OkHttpClient.Builder().readTimeout(0,TimeUnit.MILLISECONDS).build();LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff101820);
 LinearLayout c=new LinearLayout(this);c.setOrientation(1);host=field("Server Android: http://192.168.1.x:8080",false);token=field("Token dari Termux",true);c.addView(host,new LinearLayout.LayoutParams(-1,dp(36)));c.addView(token,new LinearLayout.LayoutParams(-1,dp(36)));LinearLayout cr=new LinearLayout(this);Button con=button("Hubungkan");status=new TextView(this);status.setText("Belum terhubung");status.setTextColor(-1);cr.addView(con);cr.addView(status);c.addView(cr);root.addView(c);
 LinearLayout a=new LinearLayout(this);url=field("Alamat atau kata kunci",false);url.setImeOptions(EditorInfo.IME_ACTION_GO);a.addView(url,new LinearLayout.LayoutParams(0,dp(42),1));Button go=button("Buka");a.addView(go);root.addView(a);
 page=new ImageView(this);page.setScaleType(ImageView.ScaleType.FIT_CENTER);page.setBackgroundColor(-1);root.addView(page,new LinearLayout.LayoutParams(-1,0,1));LinearLayout n=new LinearLayout(this);Button back=button("Kembali"),reload=button("Muat ulang");n.addView(back,new LinearLayout.LayoutParams(0,dp(40),1));n.addView(reload,new LinearLayout.LayoutParams(0,dp(40),1));root.addView(n);setContentView(root);
 con.setOnClickListener(v->connect());go.setOnClickListener(v->navigate());url.setOnEditorActionListener((v,x,e)->{if(x==EditorInfo.IME_ACTION_GO){navigate();return true;}return false;});back.setOnClickListener(v->action("back"));reload.setOnClickListener(v->action("refresh"));page.setOnTouchListener((v,e)->touch(e)); SharedPreferences prefs=getSharedPreferences("feather_settings",MODE_PRIVATE); host.setText(prefs.getString("server","")); token.setText(prefs.getString("token","")); if(!host.getText().toString().trim().isEmpty()&&!token.getText().toString().trim().isEmpty()) root.postDelayed(()->connect(),700); }
 void connect(){try{String s=host.getText().toString().trim(); String savedToken=token.getText().toString().trim(); getSharedPreferences("feather_settings",MODE_PRIVATE).edit().putString("server",s).putString("token",savedToken).apply();if(!s.contains("://"))s="http://"+s;Uri u=Uri.parse(s);String scheme="https".equals(u.getScheme())?"wss":"ws";String w=scheme+"://"+u.getHost()+(u.getPort()>0?":"+u.getPort():"")+"/ws?sessionId="+URLEncoder.encode(sid,"UTF-8")+"&flow=ack";Request r=new Request.Builder().url(w).header("Authorization","Bearer "+savedToken).build();if(ws!=null)ws.close(1000,"reconnect");status.setText("Menghubungkan");ws=client.newWebSocket(r,new WebSocketListener(){public void onOpen(WebSocket w,Response r){runOnUiThread(()->status.setText("Terhubung"));}public void onMessage(WebSocket w,String s){try{JSONObject j=new JSONObject(s);if("error".equals(j.optString("type")))runOnUiThread(()->status.setText(j.optString("message")));}catch(Exception e){}}public void onMessage(WebSocket w,ByteString b){byte[] d=b.toByteArray();Bitmap bm=BitmapFactory.decodeByteArray(d,0,d.length);if(bm!=null)runOnUiThread(()->page.setImageBitmap(bm));w.send("{\"type\":\"ack\"}");}public void onFailure(WebSocket w,Throwable t,Response r){runOnUiThread(()->status.setText("Gagal: "+t.getMessage()));}});}catch(Exception e){status.setText("Alamat/token tidak valid");}}
 void navigate(){String s=url.getText().toString().trim();if(s.isEmpty())return;if(!s.contains("://")){if(s.contains(" ")||!s.contains(".")){try{s="https://www.google.com/search?q="+URLEncoder.encode(s,"UTF-8");}catch(Exception e){}}else s="https://"+s;}url.setText(s);send("navigate","url",s);}
 void action(String a){send(a,null,null);}void send(String a,String k,String v){try{if(ws==null){Toast.makeText(this,"Hubungkan ke server dahulu",0).show();return;}JSONObject j=new JSONObject();j.put("type","action");j.put("action",a);if(k!=null)j.put(k,v);ws.send(j.toString());}catch(Exception e){}}
 float scale(){return Math.min(page.getWidth()/720f,page.getHeight()/720f);}float x(float v){float z=scale();return Math.max(0,Math.min(720,(v-(page.getWidth()-720*z)/2)/z));}float y(float v){float z=scale();return Math.max(0,Math.min(720,(v-(page.getHeight()-720*z)/2)/z));}
 boolean touch(MotionEvent e){float a=x(e.getX()),b=y(e.getY());if(e.getAction()==0){sx=lx=a;sy=ly=b;moved=false;return true;}if(e.getAction()==2){float dx=lx-a,dy=ly-b;if(Math.abs(a-sx)+Math.abs(b-sy)>10)moved=true;if(moved&&(Math.abs(dx)+Math.abs(dy)>1)){try{JSONObject j=new JSONObject();j.put("type","action");j.put("action","wheel");j.put("tapX",a);j.put("tapY",b);j.put("deltaX",dx);j.put("deltaY",dy);if(ws!=null)ws.send(j.toString());}catch(Exception q){}lx=a;ly=b;}return true;}if(e.getAction()==1&&!moved){try{JSONObject j=new JSONObject();j.put("type","action");j.put("action","tap");j.put("tapX",a);j.put("tapY",b);if(ws!=null)ws.send(j.toString());}catch(Exception q){}}return true;}
 public void onBackPressed(){action("back");}protected void onDestroy(){if(ws!=null)ws.close(1000,"close");super.onDestroy();}
}